import{_ as a,o as e,c as o,a2 as n}from"./chunks/framework.CgxQ0r6v.js";const g=JSON.parse('{"title":"Planificación Académica: Proyecto Sociotecnológico III (Trimestre VII)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_III/Planificacion_Trimestre_III-VII.md","filePath":"materias/Proyecto_Sociotecnologico_III/Planificacion_Trimestre_III-VII.md"}'),t={name:"materias/Proyecto_Sociotecnologico_III/Planificacion_Trimestre_III-VII.md"};function r(c,i,d,s,l,u){return e(),o("div",null,[...i[0]||(i[0]=[n('<h1 id="planificacion-academica-proyecto-sociotecnologico-iii-trimestre-vii" tabindex="-1">Planificación Académica: Proyecto Sociotecnológico III (Trimestre VII) <a class="header-anchor" href="#planificacion-academica-proyecto-sociotecnologico-iii-trimestre-vii" aria-label="Permalink to &quot;Planificación Académica: Proyecto Sociotecnológico III (Trimestre VII)&quot;">​</a></h1><p>El Proyecto Sociotecnológico III (PST III) corresponde al primer año del ciclo de Licenciatura / Ingeniería en Informática. En este trayecto, los estudiantes desarrollan sistemas de información de mayor escala y complejidad organizativa, abordando instituciones públicas, sectores socioproductivos y redes comunitarias que requieren gestión integral de datos, seguridad y servicios distribuidos.</p><hr><h2 id="📅-trimestre-vii-diagnostico-de-requerimientos-avanzados-factibilidad-y-formulacion-unidades-1-2-y-3" tabindex="-1">📅 Trimestre VII: Diagnóstico de Requerimientos Avanzados, Factibilidad y Formulación (Unidades 1, 2 y 3) <a class="header-anchor" href="#📅-trimestre-vii-diagnostico-de-requerimientos-avanzados-factibilidad-y-formulacion-unidades-1-2-y-3" aria-label="Permalink to &quot;📅 Trimestre VII: Diagnóstico de Requerimientos Avanzados, Factibilidad y Formulación (Unidades 1, 2 y 3)&quot;">​</a></h2><h3 id="📝-evaluacion-1-diagnostico-participativo-y-cuantificacion-de-datos-unidad-1" tabindex="-1">📝 Evaluación 1: Diagnóstico Participativo y Cuantificación de Datos (Unidad 1) <a class="header-anchor" href="#📝-evaluacion-1-diagnostico-participativo-y-cuantificacion-de-datos-unidad-1" aria-label="Permalink to &quot;📝 Evaluación 1: Diagnóstico Participativo y Cuantificación de Datos (Unidad 1)&quot;">​</a></h3><p><strong>Objetivo:</strong> Identificar la problemática sociotecnológica y cuantificar el volumen de información y transacciones requeridas por la organización.</p><ul><li>Abordaje a organizaciones de mayor escala (instituciones regionales, empresas de propiedad social, redes de salud o educación).</li><li>Levantamiento de información cualitativo y cuantitativo (volumen de datos, frecuencia de transacciones, concurrencia de usuarios).</li><li>Clasificación formal de Requisitos Funcionales (RF) y Requisitos No Funcionales (RNF) bajo estándares IEEE.</li><li><strong>Actividad:</strong> <strong>Informe de Diagnóstico Cuantitativo y Plan de Abordaje.</strong> (25%)</li></ul><h3 id="📝-evaluacion-2-planteamiento-del-proyecto-y-analisis-de-riesgos-unidad-2" tabindex="-1">📝 Evaluación 2: Planteamiento del Proyecto y Análisis de Riesgos (Unidad 2) <a class="header-anchor" href="#📝-evaluacion-2-planteamiento-del-proyecto-y-analisis-de-riesgos-unidad-2" aria-label="Permalink to &quot;📝 Evaluación 2: Planteamiento del Proyecto y Análisis de Riesgos (Unidad 2)&quot;">​</a></h3><p><strong>Objetivo:</strong> Formular los objetivos del proyecto y evaluar los factores de riesgo y de éxito de la solución tecnológica.</p><ul><li>Definición del problema central, objetivos y alcance del PST III.</li><li>Matriz de Análisis de Riesgos Tecnológicos, Operativos y Organizacionales (Probabilidad e Impacto).</li><li>Estrategias de mitigación de riesgos y factores críticos de éxito del proyecto.</li><li><strong>Actividad:</strong> <strong>Documento de Planteamiento del Proyecto y Matriz de Riesgos.</strong> (25%)</li></ul><h3 id="📝-evaluacion-3-estudio-de-factibilidad-multidimensional-y-costos-unidad-3" tabindex="-1">📝 Evaluación 3: Estudio de Factibilidad Multidimensional y Costos (Unidad 3) <a class="header-anchor" href="#📝-evaluacion-3-estudio-de-factibilidad-multidimensional-y-costos-unidad-3" aria-label="Permalink to &quot;📝 Evaluación 3: Estudio de Factibilidad Multidimensional y Costos (Unidad 3)&quot;">​</a></h3><p><strong>Objetivo:</strong> Determinar la viabilidad técnica, operativa, económica y legal de la propuesta de software.</p><ul><li>Factibilidad Técnica: infraestructura de servidores, base de datos distribuida o relacional y conectividad.</li><li>Factibilidad Económica y Análisis de Costos de Desarrollo (métodos de estimación como COCOMO o puntos de función).</li><li>Factibilidad Operativa y Legal: marco de la Ley de Infogobierno y adopción institucional.</li><li><strong>Actividad:</strong> <strong>Estudio de Factibilidad y Estimación de Costos / Examen.</strong> (25%)</li></ul><h3 id="📝-evaluacion-4-planificacion-cronograma-y-1er-informe-de-avance-unidades-1-a-3" tabindex="-1">📝 Evaluación 4: Planificación, Cronograma y 1er Informe de Avance (Unidades 1 a 3) <a class="header-anchor" href="#📝-evaluacion-4-planificacion-cronograma-y-1er-informe-de-avance-unidades-1-a-3" aria-label="Permalink to &quot;📝 Evaluación 4: Planificación, Cronograma y 1er Informe de Avance (Unidades 1 a 3)&quot;">​</a></h3><p><strong>Objetivo:</strong> Consolidar la planificación del ciclo de vida del proyecto y defender el primer informe formal de avance.</p><ul><li>Cronograma de actividades general (Diagrama de Gantt con hitos trimestrales).</li><li>Elaboración y entrega del 1er Informe de Avance (Documento de requisitos, factibilidad, riesgos y visitas comunitarias).</li><li>Socialización y validación del plan de trabajo con la organización.</li><li><strong>Actividad:</strong> <strong>Entrega y Defensa del 1er Informe de Avance.</strong> (25%)</li></ul><hr><h2 id="✅-resumen-del-trimestre" tabindex="-1">✅ Resumen del Trimestre <a class="header-anchor" href="#✅-resumen-del-trimestre" aria-label="Permalink to &quot;✅ Resumen del Trimestre&quot;">​</a></h2><p>Al finalizar el Trimestre VII, el equipo de ingenieros en formación dispone del diagnóstico cuantificado, el catálogo de requerimientos formalizado, los riesgos mitigados y la factibilidad demostrada, listos para iniciar el modelado arquitectónico en el Trimestre VIII.</p>',19)])])}const I=a(t,[["render",r]]);export{g as __pageData,I as default};
